mapper.select:
/* BrokerMapper.selectBrokerMasterList : broker-M 조회 */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT A.* , COUNT(A.MBL_NO) OVER() AS SUM_COUNT , SUM(A.HBL_CNT) OVER() AS SUM_HBLNO , SUM(A.HBL_PIECES) OVER() AS SUM_PIECES , SUM(A.HBL_GWT) OVER() AS SUM_GWT FROM ( SELECT MAX(od.OB_DATE) AS OB_DATE ,MAX(od.AR_DATE) AS AR_DATE ,MAX(od.ORIG_CODE) AS ORIG_CODE ,MAX(od.DEST_CODE) AS DEST_CODE ,MAX(od.VESSEL_FLIGHT) AS VESSEL_FLIGHT ,MAX(od.MBL_NO) AS MBL_NO ,COUNT(od.OD_JOB_NO) AS HBL_CNT ,COUNT(CASE WHEN ISNULL(ad.CLEARANCE_STATUS, '') = 'CLS010' THEN 1 END) CLEARANCE_VIOLATION_CNT1 ,COUNT(CASE WHEN ISNULL(ad.CLEARANCE_STATUS, '') = 'CLS030' THEN 1 END) CLEARANCE_VIOLATION_CNT2
,COUNT(CASE WHEN ISNULL(od.CLEARANCE_VIOLATION_REASON, '') != '' THEN 1 END) CLEARANCE_VIOLATION_CNT3 ,COUNT(CASE WHEN ISNULL(ad.CLEARANCE_STATUS, '') = 'CLS050' THEN 1 END) CLEARANCE_VIOLATION_CNT4 ,COUNT(CASE od.CD_TYPE WHEN 'Y' THEN 1 END) AS CD_TYPE_YCNT ,COUNT(CASE od.CD_TYPE WHEN 'N' THEN 1 END) AS CD_TYPE_NCNT ,COUNT(CASE od.CD_TYPE WHEN 'B' THEN 1 END) AS CD_TYPE_BCNT ,COUNT(CASE ad.DROP_YN WHEN 'Y' THEN 1 END) AS DROP_CNT ,COUNT(CASE od.INSPECTION_YN WHEN 'Y' THEN 1 END) AS INSPECTION_CNT ,COUNT(CASE ad.SE_INSPECTION_YN WHEN 'Y' THEN 1 END) AS SE_INSPECTION_CNT ,COUNT(CASE ad.XRAY_YN WHEN 'Y' THEN 1 END) AS XRAY_CNT ,COUNT(CASE od.GE_INSPECTION_YN WHEN 'Y' THEN 1 END) AS GE_INSPECTION_CNT ,MAX(od.INSPECTION_TYPE) AS INSPECTION_TYPE
,COUNT(CASE od.CLEARANCE_NOTICE_YN WHEN 'Y' THEN 1 END) AS CLEARANCE_NOTICE_CNT ,od.MASTER_OD_JOB_NO ,(SELECT LAST_POD_STATUS FROM TB_ECM_OD_ADDITIONAL WHERE OD_JOB_NO = od.MASTER_OD_JOB_NO) AS LAST_POD_STATUS ,MAX(od.BOUND) AS BOUND ,MAX(od.BOUND_TYPE) AS BOUND_TYPE ,SUM(od.PIECES) AS HBL_PIECES ,SUM(od.GWT) AS HBL_GWT ,COUNT(CASE WHEN ISNULL(od.ECM_YN,'') = 'Y' THEN 1 END) AS ECM_Y_CNT ,COUNT(CASE WHEN ISNULL(od.ECM_YN,'') = '' OR od.ECM_YN = 'N' THEN 1 END) AS ECM_N_CNT
,(SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = MAX(od.ENT_CODE) AND GROUP_CODE = 'CB_IF_STATUS' AND CODE = MAX(ad.CB_IF_STATUS)) AS CB_IF_STATUS ,(SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = MAX(od.ENT_CODE) AND GROUP_CODE = 'CCL_TYPE' AND CODE = MAX(ad.CCL_TYPE)) AS CCL_TYPE
FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO
AND (od.CD_TYPE IN ('N','B') OR ad.DROP_YN = 'Y')
AND 1 = 0
AND(1 = 0
OR od.INSPECTION_YN = #{srchInspectionYn}
OR ad.SE_INSPECTION_YN = #{srchSeInspectionYn}
OR ad.XRAY_YN = #{srchXrayYn}
OR ad.DROP_YN = #{srchDropYn}
OR ad.SIMPLE_EDI_STATUS = #{srchSimpleEdiStatus}
OR ad.SIMPLE_STATEMENT_YN = #{srchSimpleStatementYn}
AND ISNULL((SELECT TOP 1 ABNORMAL_CODE FROM TB_ECM_OD_ABNORMAL WHERE OD_JOB_NO = od.OD_JOB_NO),'') != ''
)
AND ad.CB_IF_STATUS = #{srchCbIfStatus}
GROUP BY od.MASTER_OD_JOB_NO )A

sql.if:
AND(1 = 0

OR od.INSPECTION_YN = #{srchInspectionYn}


OR ad.SE_INSPECTION_YN = #{srchSeInspectionYn}


