)

mapper.select:
/* BrokerMapper.selectCustomsOfficerList : 관세사지정 리스트 조회 */ SELECT ROW_NUMBER() OVER(ORDER BY MAX(od.OB_DATE) DESC, od.CUST_CODE_LV1) AS NUM ,MAX(od.OB_DATE) AS OB_DATE ,MAX(od.AR_DATE) AS AR_DATE ,MAX(od.ORIG_CODE) AS ORIG_CODE ,MAX(od.DEST_CODE) AS DEST_CODE ,MAX(od.VESSEL_FLIGHT) AS VESSEL_FLIGHT ,MAX(od.MBL_NO) AS MBL_NO ,MAX(od.CB_CODE) AS CB_CODE ,COUNT(od.OD_JOB_NO) AS HBL_CNT ,COUNT(CASE od.CD_TYPE WHEN 'Y' THEN 1 END) AS CD_TYPE_Y_CNT ,COUNT(CASE od.CD_TYPE WHEN 'N' THEN 1 END) AS CD_TYPE_N_CNT ,COUNT(CASE od.CD_TYPE WHEN 'B' THEN 1 END) AS CD_TYPE_B_CNT ,COUNT(CASE ad.DROP_YN WHEN 'Y' THEN 1 END) AS DROP_CNT ,COUNT(CASE od.INSPECTION_YN WHEN 'Y' THEN 1 END) AS INSPECTION_CNT ,COUNT(CASE ad.SE_INSPECTION_YN WHEN 'Y' THEN 1 END) AS SE_INSPECTION_CNT ,COUNT(CASE ad.XRAY_YN WHEN 'Y' THEN 1 END) AS XRAY_CNT ,COUNT(CASE od.GE_INSPECTION_YN WHEN 'Y' THEN 1 END) AS GE_INSPECTION_CNT ,MAX(od.INSPECTION_TYPE) AS INSPECTION_TYPE ,COUNT(CASE ad.SMS_INFORM_YN WHEN 'Y' THEN 1 END) AS SMS_INFORM_CNT ,od.CUST_CODE_LV1 ,(SELECT CUSTOMER_NAME_ENG FROM TB_SMS_CUSTOMER WHERE ENT_CODE = MAX(od.ENT_CODE) AND CUSTOMER_CODE = od.CUST_CODE_LV1) AS CUST_NAME_LV1 ,od.CUST_CODE_LV2 ,(SELECT CUSTOMER_NAME_ENG FROM TB_SMS_CUSTOMER WHERE ENT_CODE = MAX(od.ENT_CODE) AND CUSTOMER_CODE = od.CUST_CODE_LV2) AS CUST_NAME_LV2
FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO
WHERE od.MASTER_OD_JOB_NO = #{srchMasterOdJobNo}
WHERE od.OD_JOB_NO IN(#{item})
AND od.BL_TYPE_MH = 'H' GROUP BY od.CUST_CODE_LV1,od.CUST_CODE_LV2

sql.if:
AND(1 = 0

OR od.INSPECTION_YN = #{srchInspectionYn}


OR ad.SE_INSPECTION_YN = #{srchSeInspectionYn}


OR ad.XRAY_YN = #{srchXrayYn}


OR ad.DROP_YN = #{srchDropYn}


OR ad.SIMPLE_EDI_STATUS = #{srchSimpleEdiStatus}


OR ad.SIMPLE_STATEMENT_YN = #{srchSimpleStatementYn}


AND ISNULL((SELECT TOP 1 ABNORMAL_CODE FROM TB_ECM_OD_ABNORMAL WHERE OD_JOB_NO = od.OD_JOB_NO),'') != ''

)

mapper.update:
/* BrokerMapper.updateBrokerBatchBySrchData : Broker - 일괄변경 */
UPDATE TB_ECM_OD SET CB_CODE = #{cbCode}, CB_NAME = (SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = #{srchEntCode} AND CUSTOMER_CODE = #{cbCode} AND CUSTOMER_TYPE ='BR') FROM TB_ECM_OD od
WHERE od.MASTER_OD_JOB_NO = #{srchMasterOdJobNo}
WHERE od.OD_JOB_NO IN(#{item})
AND od.BL_TYPE_MH = 'H'
AND od.CUST_CODE_LV1 = #{custCodeLv1} AND ISNULL(od.CUST_CODE_LV2,'') = #{custCodeLv2}
AND 1 = 0
UPDATE ad SET CLEARANCE_STATUS = 'CLS050' ,CLEARANCE_YN = 'Y' FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO
UPDATE od SET CLEARANCE_VIOLATION_CODE = #{clearanceViolationCode} ,CLEARANCE_VIOLATION_REASON = #{clearanceViolationReason} FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO
SELECT @@ROWCOUNT AS COUNT

/* BrokerMapper.updateBrokerBatchBySrchData2 : Broker - 통관상태 일괄변경 */
UPDATE ad SET
CLEARANCE_STATUS = CASE WHEN ISNULL(od.CB_CODE, '') != '' THEN 'CLS030' ELSE 'CLS010' END FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO
WHERE od.MASTER_OD_JOB_NO = #{srchMasterOdJobNo}
WHERE od.OD_JOB_NO IN(#{item})
AND od.BL_TYPE_MH = 'H' AND od.CUST_CODE_LV1 = #{custCodeLv1} AND ISNULL(od.CUST_CODE_LV2,'') = #{custCodeLv2}
AND od.CD_TYPE IN ('N','B')
UPDATE ad SET CLEARANCE_STATUS = 'CLS040' FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO
SELECT @@ROWCOUNT AS COUNT

/* BrokerMapper.updateTariffRemarks : 통관결과값 관세사 비고에 업데이트 */
	UPDATE TB_ECM_OD
	SET TARIFF_REMARKS = #{tariffRemarks}
	WHERE OD_JOB_NO = #{odJobNo}
